        this.request = mock(ServerHttpRequest.class);
        this.exchangeAttributes = new HashMap<>();
        this.exchange = mock(ServerWebExchange.class);
        when(this.exchange.getResponse()).thenReturn(this.response);
        when(this.exchange.getRequest()).thenReturn(this.request);
        when(this.exchange.getAttributes()).thenReturn(this.exchangeAttributes);

        this.requestContext = mock(RequestContext.class);
        when(this.requestContext.getRequestDataValueProcessor()).thenReturn(null);

        this.engineStream = Flux.empty();
