        when(this.templateEngine.processStream(
                any(String.class), any(), any(IContext.class), any(DataBufferFactory.class),
                any(MediaType.class), any(Charset.class), anyInt()))
                .thenAnswer(invocation -> {
                    this.engineProcessStreamInvocations++;
                    this.capturedTemplateName = invocation.getArgument(0);
                    this.capturedMarkupSelectors = invocation.getArgument(1);
                    this.capturedContext = invocation.getArgument(2);
                    this.capturedBufferFactory = invocation.getArgument(3);
                    this.capturedMediaType = invocation.getArgument(4);
                    this.capturedCharset = invocation.getArgument(5);
                    this.capturedMaxChunkSizeBytes = invocation.getArgument(6);
                    return this.engineStream;
