    private static List<List<DataBuffer>> collectFlushedGroups(final Publisher<?> flushPublisher) {
        return Flux.from((Publisher<Publisher<? extends DataBuffer>>) flushPublisher)
                .concatMap(window -> Flux.from(window).collectList())
                .collectList()
                .block();
    }


    @Test
