        final IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, result::block);
        assertEquals("Property 'templateName' is required", exception.getMessage());
        assertEquals(0, this.engineProcessStreamInvocations);
        verify(this.templateEngine, never()).processStream(
                any(String.class), any(), any(IContext.class), any(DataBufferFactory.class),
