    @Test
    void fullModeWritesWithEngineStreamAndPopulatesContext() {

        final ThymeleafReactiveView view = newView();
        view.addStaticVariable("staticVar", "staticValue");

        this.exchangeAttributes.put(
                HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE, Collections.singletonMap("pathVar", "pathValue"));

        final Map<String, Object> renderAttributes = new HashMap<>();
        renderAttributes.put("modelAttr", "modelValue");

        final MediaType contentType = htmlWithUtf8ContentType();

        final Mono<Void> result = view.render(null, renderAttributes, contentType, this.exchange);
        assertNull(result.block());

        // FULL mode: the engine stream is directly handed over to writeWith(...)
        verify(this.response).writeWith(this.engineStream);
        verify(this.response, never()).writeAndFlushWith(any(Publisher.class));

        assertEquals(1, this.engineProcessStreamInvocations);
        assertEquals(VIEW_TEMPLATE_NAME, this.capturedTemplateName);
        assertNull(this.capturedMarkupSelectors);
        assertSame(this.bufferFactory, this.capturedBufferFactory);
        assertSame(contentType, this.capturedMediaType);
        assertEquals(StandardCharsets.UTF_8, this.capturedCharset);
        assertEquals(Integer.MAX_VALUE, this.capturedMaxChunkSizeBytes);

        // The locale of the view is applied to the response headers
        assertEquals("es-ES", this.responseHeaders.getFirst(HttpHeaders.CONTENT_LANGUAGE));

        final IContext context = this.capturedContext;
        assertNotNull(context);
        assertEquals(VIEW_LOCALE, context.getLocale());
        assertEquals("staticValue", context.getVariable("staticVar"));
        assertEquals("pathValue", context.getVariable("pathVar"));
        assertEquals("modelValue", context.getVariable("modelAttr"));

        assertSame(this.requestContext,
                context.getVariable(SpringContextVariableNames.SPRING_REQUEST_CONTEXT));

        final Object thymeleafRequestContext =
                context.getVariable(SpringContextVariableNames.THYMELEAF_REQUEST_CONTEXT);
        assertInstanceOf(SpringWebFluxThymeleafRequestContext.class, thymeleafRequestContext);
        assertSame(this.exchange, ((SpringWebFluxThymeleafRequestContext) thymeleafRequestContext).getServerWebExchange());

        final Object evaluationContext =
                context.getVariable(ThymeleafEvaluationContext.THYMELEAF_EVALUATION_CONTEXT_CONTEXT_VARIABLE_NAME);
        assertInstanceOf(ThymeleafEvaluationContext.class, evaluationContext);
        assertSame(this.applicationContext, ((ThymeleafEvaluationContext) evaluationContext).getApplicationContext());

        // No conversion service bean configured at the application context
        verify(this.applicationContext, never()).getBean(WEBFLUX_CONVERSION_SERVICE_NAME);
    }


